(()=>{'use strict';const params=new URLSearchParams(location.search);if(params.get('embedded')!=='1')return;document.documentElement.classList.add('modern-embedded');function applyTheme(dark){document.documentElement.classList.toggle('modern-dark',dark)}applyTheme(params.get('theme')==='dark');window.addEventListener('message',ev=>{if(ev.origin!==location.origin||ev.source!==parent)return;if(ev.data?.type==='missao-theme')applyTheme(!!ev.data.dark)});function open(){document.documentElement.classList.remove('p8-entry-check');const welcome=document.getElementById('p8FirstVisit');if(welcome)welcome.hidden=true;const tool=params.get('tool');if(tool&&document.getElementById(tool)?.classList.contains('view')&&typeof showView==='function'){showView(tool);window.scrollTo(0,0)}}if(document.readyState==='complete')open();else window.addEventListener('load',open,{once:true});document.addEventListener('portal8:viewchange',ev=>{parent.postMessage({type:'missao-route',id:ev.detail?.id},location.origin)});})();
